from collections import deque

def find_path(graph, start, goal):
    if start == goal:
        return [start]  # The start node is the goal node itself

    visited = set()     # Set to track visited nodes
    queue = deque([(start, [start])])  # Queue for BFS with tuple (node, path)

    while queue:
        (current_node, path) = queue.popleft()  

        if current_node == goal:
            return path  # Goal node found, return the path

        if current_node not in visited:  
            visited.add(current_node)  # Mark current node as visited

            for neighbor in graph.get(current_node, []):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))  # Add neighbor to queue

    return None  # Goal node not reachable

