def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Dictionary to store the path
    path = {start: []}
    visited = {start}
    while goal not in path:
        # Select the next node to visit, I'm using the node with the smallest degree
        # which ensures the shortest path is found if there's a tie
        candidates = {node: deg for node, deg in path.items() if deg[0] == min(deg[0], deg[1])}
        if not candidates:
            return None
        current_node = min(candidates, key=lambda k: (candidates[k][0], candidates[k][1]))

        # Path is formed if goal is met
        if goal in graph.get(current_node, []):
            path[goal].append(current_node)
        else:
            path[goal] = [current_node]

        for neighbor in set(graph.get(current_node, [])).difference(visited):
            visited.add(neighbor)
            path[neighbor] = [current_node] + path.get(neighbor, [current_node])

    # Reconstruct the path from goal to start
    path_list = []
    while goal:
        path_list.append(goal)
        goal = path[goal][0]
    path_list.reverse()

    return path_list

