def find_path(graph, start, goal):
    """
    Perform a depth-first search (DFS) to find a path from start to goal.
    :param graph: A dictionary where keys are nodes and values are lists of neighboring nodes.
    :param start: The starting node.
    :param goal: The goal node to reach.
    :return: A list representing the path from start to goal, or None if goal is unreachable.
    """
    def dfs(node, path):
        if node == goal:
            return path
        for neighbor in graph[node]:
            if neighbor not in path:
                new_path = dfs(neighbor, path + [neighbor])
                if new_path:
                    return new_path
        return None

    return dfs(start, [start])
