def find_path(graph, start, goal):
    from heapq import heappop, heappush
    import itertools

    if start is None or goal is None:
        return None

    queue = [(0, start, [start])]  # (cost, current_node, path)
    visited = set()
    came_from = {start: None}

    while queue:
        (cost, current_node, path) = heappop(queue)

        if current_node == goal:
            return path

        if current_node not in visited:
            visited.add(current_node)
            for next_node in graph[current_node]:
                if next_node not in visited:
                    priority = cost + 1  # A* uses a heuristic to optimize, here a plain weight heuristic.
                    heappush(queue, (priority, next_node, path + [next_node]))
                    came_from[next_node] = current_node

    return None

