def find_path(graph, start, goal):
    # Initialize the priority queue with (0, start)
    queue = [(0, start)]
    # Dictionary to keep track of parent nodes
    parents = {start: None}
    # Dictionary to keep track of the cost from start to each node
    costs = {start: 0}

    while queue:
        (cost, current) = queue.pop(0)

        if current == goal:
            # Reconstruct the path
            path = []
            while current:
                path.append(current)
                current = parents[current]
            return path[::-1]  # Return the path in reverse

        for neighbor in graph[current]:
            if neighbor in costs:
                continue  # Skip it as we've already processed it
            new_cost = costs[current] + 1
            if neighbor not in costs or new_cost < costs[neighbor]:
                costs[neighbor] = new_cost
                priority = new_cost
                parent = current
                queue.append((priority, neighbor))
                parents[neighbor] = parent
                queue.sort()  # Maintain the queue with the lowest cost at the start

    return None
